mapper.select:
SELECT DISTINCT deviceCode, devName, height, streetCode, streetName, status, deviceStatusName, orderStatusName, orderStatus, longitude, latitude, location, tenantId, industry_code, provinceName, provinceCode, cityName, cityCode, countryName, countryCode, modelId, categoryCode, modelName, collectType, collectMethod, siteCode, deviceModelCode, visualRadius FROM ( SELECT DISTINCT od.device_code as deviceCode, ( case when length(IFNULL(ten.device_name, '')) = 0 then m.device_name else ten.device_name end ) devName,
( case when length(IFNULL(ten.channel_name, '')) = 0 then ci.channel_name else ten.channel_name end ) chanName,
m.town_code as streetCode, town.area_name as streetName, m.device_status as status, (CASE WHEN m.device_status = '0' THEN '在线' WHEN m.device_status = '1' THEN '离线' WHEN m.device_status = '2' THEN '从未连接' END) deviceStatusName, (CASE WHEN od.ord_status in ('0','1','2') THEN '有效' WHEN od.ord_status = '3' THEN '退订' WHEN od.ord_status = '4' THEN '失效' END) orderStatusName, od.ord_status as orderStatus, m.longitude, m.latitude, m.location, m.height, m.collect_type collectType, m.collect_method collectMethod, m.device_model_code deviceModelCode, m.site_code siteCode, od.tenant_id as tenantId, od.industry_code, pro.area_name as provinceName, pro.area_code as provinceCode, city.area_name as cityName, city.area_code as cityCode, county.area_name as countryName, county.area_code as countryCode, m.model_code as modelId, m.category_code as categoryCode, m.visual_radius as visualRadius, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = '103' AND DICT_VALUE = m.model_code limit 1) modelName FROM vm_order_devices od LEFT JOIN vm_device_info_t m on m.device_code = od.device_code LEFT JOIN vm_tenant_device_channel_rel_t ten on ten.device_code = od.device_code and ten.tenant_id =#{param.tenantId}od.tenant_id and ten.delete_flag='0' and ten.industry_code = #{param.industryCode}od.industry_code LEFT JOIN sys_area pro on pro.area_code = m.province_id LEFT JOIN sys_area city on city.area_code = m.city_id LEFT JOIN sys_area county on county.area_code = m.county_id LEFT JOIN sys_area town on town.area_code = m.town_code
LEFT JOIN vm_organ_device_rel_t vod on vod.device_code = m.device_code and vod.delete_flag = '0' and vod.tenant_id = od.tenant_id and vod.device_type = 4
LEFT JOIN vm_channel_info_t ci ON ci.device_code = od.device_code where od.delete_flag = '0' AND m.delete_flag = '0' AND ci.delete_flag = '0'
and vod.dept_id in
#{id}
and m.device_code in
#{id}
AND m.province_id = #{param.provinceCode}
AND m.city_id = #{param.cityCode}
AND m.county_id = #{param.countryCode}
AND m.town_code = #{param.townCode}
and m.device_code like CONCAT('%', #{param.deviceCode}, '%')
and m.device_code = #{param.deviceCode}
and m.device_status = #{param.status}
and m.model_code = #{param.modelId}
and od.ord_status in (0, 1, 2)
and od.ord_status = #{param.orderStatus}
and ci.channel_code like CONCAT('%', #{param.channelCode}, '%')
${param.dataScope} ORDER BY field(od.ord_status,1,0,2,4,3) ASC
and m.device_code = #{param.deviceCode}
) dt
and dt.devName like CONCAT('%', #{param.devName}, '%')
and dt.chanName like CONCAT('%', #{param.channelName}, '%')
GROUP BY tenantId,industry_code,deviceCode ORDER BY provinceCode,cityCode,countryCode,streetCode,deviceCode

SELECT t1.category_code, (SELECT DICT_LABEL FROM sys_dict_data WHERE dict_type = 'full_view_device_type' AND DICT_VALUE = t1.category_code) AS deviceTypeName, COUNT(*) AS deviceTypeNum FROM vm_device_info_t t1 WHERE t1.category_code IS NOT NULL and t1.delete_flag = '0'
and t1.device_code in
#{id}
GROUP BY t1.category_code;

select r.device_code, l.label_id, l.label_name
from vm_device_labels_rel r
inner join vm_tenant_label_config l on r.label_id = l.label_id
where l.tenant_id = #{tenantId} and l.industry_code = #{industryCode}

    and r.device_code in

        #{item}
